CREATE TABLE doris_book.partition_events(d DATE,id INT,v INT) DUPLICATE KEY(d,id) PARTITION BY RANGE(d)(PARTITION p1 VALUES LESS THAN ('2026-10-02'),PARTITION p2 VALUES LESS THAN ('2026-10-03')) DISTRIBUTED BY HASH(id) BUCKETS 1 PROPERTIES('replication_num'='1'); SHOW PARTITIONS FROM doris_book.partition_events; INSERT INTO doris_book.partition_events VALUES('2026-10-01',1,10),('2026-10-02',2,20); SHOW PARTITIONS FROM doris_book.partition_events; SELECT d,COUNT(*),SUM(v) FROM doris_book.partition_events GROUP BY d ORDER BY d;
